const shards = Array.from({ length: N }, (_, i) => {
  const r = (o) => hash(i * 13 + o + 1);
  const cols = 6;
  const rows = 6;
  const col = i % cols;
  const row = Math.floor(i / cols);
  const cw = width / cols;
  const ch = height / rows;
  const cx = col * cw + cw / 2 - width / 2;
  const cy = row * ch + ch / 2 - height / 2;
  const ang = Math.atan2(cy, cx);
  const pts = [
